import java.io.*;
import java.nio.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/**
 * PaymentBatchProcessor - processes uploaded payment batch files
 * Uses off-heap memory for performance with large batch files
 * Implements resource pooling to reduce GC pressure
 */
public class PaymentBatchProcessor {

    private static final int BUFFER_SIZE = 4096;
    private final ConcurrentLinkedQueue<DirectBufferWrapper> bufferPool;
    private final AtomicInteger activeLeases;
    private final ExecutorService validationExecutor;
    private final ExecutorService settlementExecutor;

    public PaymentBatchProcessor() {
        this.bufferPool = new ConcurrentLinkedQueue<>();
        this.activeLeases = new AtomicInteger(0);
        this.validationExecutor = Executors.newFixedThreadPool(4);
        this.settlementExecutor = Executors.newFixedThreadPool(2);
        // Pre-allocate pool
        for (int i = 0; i < 8; i++) {
            bufferPool.offer(new DirectBufferWrapper(ByteBuffer.allocateDirect(BUFFER_SIZE)));
        }
    }

    static class DirectBufferWrapper {
        private ByteBuffer buffer;
        private final AtomicInteger refCount;
        private volatile boolean deallocated;

        DirectBufferWrapper(ByteBuffer buffer) {
            this.buffer = buffer;
            this.refCount = new AtomicInteger(1);
            this.deallocated = false;
        }

        public ByteBuffer acquire() {
            refCount.incrementAndGet();
            return buffer;
        }

        public void release() {
            int remaining = refCount.decrementAndGet();
            if (remaining <= 0) {
                deallocate();
            }
        }

        private synchronized void deallocate() {
            if (!deallocated) {
                deallocated = true;
                sun.misc.Unsafe unsafe = getUnsafe();
                if (buffer != null && buffer.isDirect()) {
                    // Force deallocation of direct buffer
                    ((sun.nio.ch.DirectBuffer) buffer).cleaner().clean();
                    buffer = null;
                }
            }
        }

        public boolean isDeallocated() { return deallocated; }

        private static sun.misc.Unsafe getUnsafe() {
            try {
                java.lang.reflect.Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
                f.setAccessible(true);
                return (sun.misc.Unsafe) f.get(null);
            } catch (Exception e) { throw new RuntimeException(e); }
        }
    }

    public CompletableFuture<BatchResult> processBatch(InputStream uploadStream) {
        return CompletableFuture.supplyAsync(() -> {
            DirectBufferWrapper wrapper = acquireBuffer();
            BatchContext ctx = new BatchContext(wrapper);
            try (InputStream in = uploadStream) {
                byte[] temp = new byte[BUFFER_SIZE];
                int bytesRead = in.read(temp);
                if (bytesRead > 0) {
                    ByteBuffer buf = wrapper.acquire();
                    buf.clear();
                    buf.put(temp, 0, bytesRead);
                    buf.flip();
                    wrapper.release();
                }
                return ctx;
            } catch (IOException e) {
                wrapper.release();
                throw new CompletionException(e);
            }
        }, validationExecutor)
        .thenCompose(ctx -> validateAndSettle(ctx));
    }

    private CompletableFuture<BatchResult> validateAndSettle(BatchContext ctx) {
        CompletableFuture<ValidationResult> validation = CompletableFuture.supplyAsync(() -> {
            return validatePayments(ctx);
        }, validationExecutor);

        CompletableFuture<BatchResult> settlement = validation.thenApplyAsync(vResult -> {
            if (!vResult.isValid()) {
                ctx.getBuffer().release();
                return new BatchResult(false, "Validation failed");
            }
            BatchResult result = settlePayments(ctx);
            ctx.getBuffer().release();
            return result;
        }, settlementExecutor);

        return settlement;
    }

    private ValidationResult validatePayments(BatchContext ctx) {
        ByteBuffer buf = ctx.getBuffer().acquire();
        try {
            if (buf == null || !buf.hasRemaining()) {
                return new ValidationResult(false);
            }
            // Parse and validate payment records
            byte marker = buf.get(0);
            if (marker != 0x50) { // 'P' for payment batch
                return new ValidationResult(false);
            }
            return new ValidationResult(true);
        } finally {
            ctx.getBuffer().release();
        }
    }

    private BatchResult settlePayments(BatchContext ctx) {
        ByteBuffer buf = ctx.getBuffer().acquire();
        try {
            // Process settlement
            return new BatchResult(true, "Settled");
        } finally {
            ctx.getBuffer().release();
        }
    }

    private DirectBufferWrapper acquireBuffer() {
        DirectBufferWrapper wrapper = bufferPool.poll();
        if (wrapper == null || wrapper.isDeallocated()) {
            wrapper = new DirectBufferWrapper(ByteBuffer.allocateDirect(BUFFER_SIZE));
        }
        activeLeases.incrementAndGet();
        return wrapper;
    }

    public void returnBuffer(DirectBufferWrapper wrapper) {
        if (!wrapper.isDeallocated()) {
            activeLeases.decrementAndGet();
            bufferPool.offer(wrapper);
        }
    }

    static class BatchContext {
        private final DirectBufferWrapper buffer;
        BatchContext(DirectBufferWrapper buffer) { this.buffer = buffer; }
        DirectBufferWrapper getBuffer() { return buffer; }
    }

    static class ValidationResult {
        private final boolean valid;
        ValidationResult(boolean valid) { this.valid = valid; }
        boolean isValid() { return valid; }
    }

    static class BatchResult {
        private final boolean success;
        private final String message;
        BatchResult(boolean success, String message) { this.success = success; this.message = message; }
        boolean isSuccess() { return success; }
    }
}
